#include <stdint.h>
#include <string.h>
#include <stdlib.h>

#define XXH_NAMESPACE LZ4_
#include "xxhash.h"
#include "lz4.h"

#define FUZZ_RNG_SEED_SIZE 4
#define MIN(a, b) ((a) < (b) ? (a) : (b))

static uint32_t FUZZ_seed(uint8_t const **src, size_t* size) {
    uint8_t const *data = *src;
    size_t const toHash = MIN(FUZZ_RNG_SEED_SIZE, *size);
    *size -= toHash;
    *src += toHash;
    return LZ4_XXH32(data, toHash, 0);
}

#define FUZZ_rotl32(x, r) (((x) << (r)) | ((x) >> (32 - (r))))

static uint32_t FUZZ_rand(uint32_t *state) {
    static const uint32_t prime1 = 2654435761U;
    static const uint32_t prime2 = 2246822519U;
    uint32_t rand32 = *state;
    rand32 *= prime1;
    rand32 += prime2;
    rand32 = FUZZ_rotl32(rand32, 13);
    *state = rand32;
    return rand32 >> 5;
}

static uint32_t FUZZ_rand32(uint32_t *state, uint32_t min, uint32_t max) {
    uint32_t random = FUZZ_rand(state);
    return min + (random % (max - min + 1));
}

int main() {
    // Data size after seed (200000 bytes of zeros)
    size_t data_size = 200000;
    int compressBound = LZ4_compressBound(data_size);

    printf("data_size=%zu, LZ4_compressBound=%d\n", data_size, compressBound);

    // Try all possible 4-byte seeds to find ones that give dstCapacity in range [785, 800]
    // That's 4 billion possibilities, too many. Let's try specific patterns.

    // Target: dstCapacity around 790-800
    int target_min = 785;
    int target_max = 810;

    uint8_t seed_bytes[4];
    int found = 0;

    for (uint32_t i = 0; i < 0xFFFFFFFF && found < 20; i++) {
        memcpy(seed_bytes, &i, 4);

        const uint8_t *ptr = seed_bytes;
        size_t sz = 4 + data_size;  // total input size
        size_t seed_sz = sz;

        uint32_t seed = FUZZ_seed(&ptr, &seed_sz);
        // After FUZZ_seed: seed_sz = sz - 4 = data_size

        size_t dstCapacity = FUZZ_rand32(&seed, 0, compressBound);

        if (dstCapacity >= target_min && dstCapacity <= target_max) {
            printf("FOUND: seed_bytes=%02x%02x%02x%02x -> dstCapacity=%zu\n",
                   seed_bytes[0], seed_bytes[1], seed_bytes[2], seed_bytes[3],
                   dstCapacity);
            found++;
        }

        if (i % 100000000 == 0) {
            printf("Progress: %u / 4294967295\n", i);
            fflush(stdout);
        }
    }

    return 0;
}"}

